export const uid=()=>crypto.randomUUID();
const library={Chest:['Bench press','Incline dumbbell press','Dumbbell press','Chest fly','Cable fly','Push-up','Chest dip'],Back:['Barbell row','Lat pulldown','Seated cable row','Pull-up','Chin-up','Dumbbell row','Deadlift'],Legs:['Back squat','Front squat','Leg press','Romanian deadlift','Leg curl','Leg extension','Bulgarian split squat','Walking lunge','Hip thrust','Calf raise'],Shoulders:['Shoulder press','Dumbbell shoulder press','Lateral raise','Rear delt fly','Face pull'],Arms:['Barbell curl','Dumbbell curl','Hammer curl','Cable curl','Triceps pushdown','Overhead triceps extension','Skull crusher'],Core:['Crunch','Cable crunch','Hanging leg raise','Ab wheel rollout']};
export const exercises=Object.entries(library).flatMap(([muscle,names])=>names.map(name=>({id:name.toLowerCase().replaceAll(' ','-'),name,muscle})));
export const newSet=(weight=null,reps=null,type='normal')=>({id:uid(),weight,reps,type,done:false});
export function initialState(){return {version:1,exercises:structuredClone(exercises),workouts:[],draft:null,routines:[{id:uid(),name:'Upper body',items:['bench-press','barbell-row','shoulder-press','lat-pulldown','triceps-pushdown'].map(exerciseId=>({exerciseId,group:null,sets:[{weight:null,reps:null,type:'normal'},{weight:null,reps:null,type:'normal'},{weight:null,reps:null,type:'normal'}]}))},{id:uid(),name:'Lower body',items:['back-squat','romanian-deadlift','leg-curl','calf-raise'].map(exerciseId=>({exerciseId,group:null,sets:Array.from({length:3},()=>({weight:null,reps:null,type:'normal'}))}))},{id:uid(),name:'Full body',items:['back-squat','bench-press','lat-pulldown','lateral-raise'].map(exerciseId=>({exerciseId,group:null,sets:Array.from({length:3},()=>({weight:null,reps:null,type:'normal'}))}))}],settings:{unit:'kg',rest:90,restEnds:null,lastBackup:null}}}
export const localDay=(v=new Date())=>{const d=new Date(v);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
export function activityDays(state,count=112,now=new Date()){const dates=new Map();for(const w of state.workouts){const k=localDay(w.started),v=dates.get(k)||{count:0,minutes:0};v.count++;v.minutes+=Math.max(0,(Date.parse(w.ended)-Date.parse(w.started))/60000);dates.set(k,v)}const today=localDay(now);return Array.from({length:count},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth(),now.getDate()-(count-7)-now.getDay()+i,12);const key=localDay(d),v=dates.get(key)||{count:0,minutes:0},plans=state.settings.scheduleHistory||[],plan=plans.filter(p=>p.from<=key).at(-1),scheduled=plan?plan.days:(plans.length?[]:state.settings.schedule||[]);return {date:key,count:v.count,minutes:Math.round(v.minutes),level:v.minutes<30?1:v.minutes<60?2:v.minutes<90?3:4,status:key>today?'future':v.count?'trained':key<today&&key>=(state.settings.trackingSince||today)&&scheduled.includes(d.getDay())?'missed':key===today&&scheduled.includes(d.getDay())?'planned':'rest'}})};
export const toDisplay=(kg,unit)=>kg==null?'':Math.round(kg*(unit==='lb'?2.20462262185:1)*100)/100;
export const toKg=(value,unit)=>Number(value)/(unit==='lb'?2.20462262185:1);
export const validSet=s=>Number.isFinite(s.weight)&&s.weight>=0&&s.weight<=10000&&Number.isInteger(s.reps)&&s.reps>0&&s.reps<=1000;
export const workingSets=w=>w.entries.flatMap(e=>e.sets.filter(s=>s.done&&s.type!=='warmup'&&validSet(s)));
export const volume=w=>workingSets(w).reduce((n,s)=>n+s.weight*s.reps,0);
export function bestFor(workouts,exerciseId){const sets=workouts.flatMap(w=>w.entries.filter(e=>e.exerciseId===exerciseId).flatMap(e=>e.sets.filter(s=>s.done&&s.type==='normal'&&validSet(s)).map(s=>({...s,date:w.ended}))));return {weight:sets.length?Math.max(...sets.map(s=>s.weight)):null,reps:sets.length?Math.max(...sets.map(s=>s.reps)):null,e1rm:sets.filter(s=>s.reps<=12).length?Math.max(...sets.filter(s=>s.reps<=12).map(s=>s.weight*(s.reps===1?1:1+s.reps/30))):null};}
export const previousEntries=(workouts,id)=>[...workouts].sort((a,b)=>Date.parse(b.ended)-Date.parse(a.ended)).filter(w=>w.entries.some(e=>e.exerciseId===id));
export function startWorkout(state,routine=null){return {id:uid(),name:routine?.name||'Today’s workout',started:new Date().toISOString(),ended:null,notes:'',entries:(routine?.items||[]).map(item=>({id:uid(),exerciseId:item.exerciseId,group:item.group||null,sets:item.sets.map(s=>newSet(s.weight,s.reps,s.type))}))};}
export function finishWorkout(draft,ended=new Date().toISOString()){const w=structuredClone(draft);w.ended=ended;w.entries=w.entries.map(e=>({...e,sets:e.sets.filter(s=>s.done&&validSet(s))})).filter(e=>e.sets.length);if(!w.entries.length)throw Error('Complete at least one set before finishing.');for(const e of w.entries)e.sets.forEach((s,i)=>{if(s.type==='drop'&&(!i||e.sets[i-1].type==='warmup'))s.type='normal'});normalizeGroups(w.entries);return w;}
export function normalizeGroups(entries){for(const e of entries)if(e.group&&entries.filter(x=>x.group===e.group).length<2)e.group=null;}
export function validateBackup(data){
 const fail=()=>{throw Error('This is not a valid Setline backup. Your current data has not changed.')};
 const string=(v,max=200)=>typeof v==='string'&&v.length<=max;
 const id=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(v);
 const unique=a=>a.length===new Set(a.map(x=>x.id)).size;
 const date=v=>typeof v==='string'&&Number.isFinite(Date.parse(v));
 if(!data||data.version!==1||!Array.isArray(data.exercises)||!Array.isArray(data.workouts)||!Array.isArray(data.routines)||data.exercises.length>2000||data.workouts.length>20000||data.routines.length>500)fail();
 if(!unique(data.exercises)||!unique(data.workouts)||!unique(data.routines))fail();
 if(data.exercises.some(e=>!e||!id(e.id)||!string(e.name,120)||!e.name.trim()||!string(e.muscle,50)))fail();
 const ex=new Set(data.exercises.map(e=>e.id));
 const set=(s,completed=false)=>{if(!s||!id(s.id)||!['normal','warmup','drop'].includes(s.type)||typeof s.done!=='boolean'||(s.weight!==null&&(!Number.isFinite(s.weight)||s.weight<0||s.weight>10000))||(s.reps!==null&&(!Number.isInteger(s.reps)||s.reps<1||s.reps>1000))||((s.done||completed)&&!validSet(s))||(completed&&!s.done))fail();return {id:s.id,weight:s.weight,reps:s.reps,type:s.type,done:s.done}};
 const workout=(w,completed)=>{if(!w||!id(w.id)||!string(w.name,120)||!date(w.started)||(completed&&(!date(w.ended)||Date.parse(w.ended)<Date.parse(w.started)))||(!completed&&w.ended!==null)||!string(w.notes,10000)||!Array.isArray(w.entries)||w.entries.length>150||!unique(w.entries))fail();const entries=w.entries.map(e=>{if(!e||!id(e.id)||!ex.has(e.exerciseId)||(e.group!==null&&!id(e.group))||!Array.isArray(e.sets)||e.sets.length>200||!unique(e.sets))fail();const sets=e.sets.map(s=>set(s,completed));for(let i=0;i<sets.length;i++)if(sets[i].type==='drop'&&(i===0||sets[i-1].type==='warmup'))fail();return {id:e.id,exerciseId:e.exerciseId,group:e.group,sets}});normalizeGroups(entries);return {id:w.id,name:w.name,started:w.started,ended:completed?w.ended:null,notes:w.notes,entries}};
 const settings=data.settings;if(!settings||!['kg','lb'].includes(settings.unit)||!Number.isInteger(settings.rest)||settings.rest<0||settings.rest>600||(settings.restEnds!==null&&!Number.isFinite(settings.restEnds))||(settings.lastBackup!==null&&!date(settings.lastBackup)))fail();
 const result={version:1,exercises:data.exercises.map(({id,name,muscle})=>({id,name,muscle})),workouts:data.workouts.map(w=>workout(w,true)),draft:data.draft===null?null:workout(data.draft,false),routines:data.routines.map(r=>{if(!r||!id(r.id)||!string(r.name,120)||!Array.isArray(r.items)||r.items.length>150)fail();const items=r.items.map(e=>{if(!ex.has(e.exerciseId)||(e.group!==null&&!id(e.group))||!Array.isArray(e.sets)||e.sets.length>200)fail();const sets=e.sets.map(s=>{const clean=set({...s,id:'template',done:false});return {weight:clean.weight,reps:clean.reps,type:clean.type}});for(let i=0;i<sets.length;i++)if(sets[i].type==='drop'&&(i===0||sets[i-1].type==='warmup'))fail();return {exerciseId:e.exerciseId,group:e.group,sets}});normalizeGroups(items);return {id:r.id,name:r.name,items}}),settings:{unit:settings.unit,rest:settings.rest,restEnds:settings.restEnds,lastBackup:settings.lastBackup}};
 const schedule=settings.schedule??[];if(!Array.isArray(schedule)||schedule.length>7||new Set(schedule).size!==schedule.length||schedule.some(x=>!Number.isInteger(x)||x<0||x>6))fail();if(settings.trackingSince!==undefined&&(!/^\d{4}-\d{2}-\d{2}$/.test(settings.trackingSince)||!date(settings.trackingSince)))fail();result.settings.schedule=schedule;result.settings.trackingSince=settings.trackingSince||localDay();
 const history=settings.scheduleHistory??[];if(!Array.isArray(history)||history.length>10000)fail();result.settings.scheduleHistory=history.map(h=>{if(!h||!/^\d{4}-\d{2}-\d{2}$/.test(h.from)||!date(h.from)||!Array.isArray(h.days)||h.days.length>7||new Set(h.days).size!==h.days.length||h.days.some(x=>!Number.isInteger(x)||x<0||x>6))fail();return {from:h.from,days:[...h.days]}}).sort((a,b)=>a.from.localeCompare(b.from));
 if(result.draft&&result.workouts.some(w=>w.id===result.draft.id))fail();return result;
}
export function csvExport(state){const q=x=>'"'+String(x??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const rows=[['workout_id','workout','started','ended','exercise','muscle','superset_group','set','type','weight','unit','reps','notes']];for(const w of state.workouts)for(const e of w.entries){const ex=state.exercises.find(x=>x.id===e.exerciseId);e.sets.filter(s=>s.done).forEach((s,i)=>rows.push([w.id,w.name,w.started,w.ended,ex?.name,ex?.muscle,e.group,i+1,s.type,toDisplay(s.weight,state.settings.unit),state.settings.unit,s.reps,w.notes]))}return '\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n');}
